(async()=>{
 const R=[];
 for(let n=0;n<7;n++){
  window.__mc.ir(n); window.__mc.sinBichos(); window.__mc.vidas(999);
  const meta=window.__mc.meta();
  let mejor=0, quieto=0, ultimo=-1, listo=false, caidas=0, pasos=0;
  for(let k=0;k<2600;k++){
   const e=window.__mc.estado();
   if(e.jug[0]>mejor) mejor=e.jug[0];
   if(Math.abs(e.jug[0]-meta[0])<40 && Math.abs(e.jug[1]-meta[1])<70){ listo=true; break; }
   if(e.jug[0]===ultimo) quieto++; else { quieto=0; ultimo=e.jug[0]; }
   if(quieto>=2){ window.__mc.saltar(); window.__mc.correr(22,1); quieto=0; }
   else window.__mc.correr(5,1);
   pasos++;
   if(window.__mc.estado().vidas<999){ caidas++; window.__mc.vidas(999); }
  }
  R.push({n:n+1, llego:listo, x:Math.round(mejor), metaX:meta[0], caidas, pasos});
 }
 return R;})()
